"""只读 PyPI 元数据快照；不是安装器、解析器或依赖版本求解器。"""
import concurrent.futures
import datetime
import hashlib
import json
from pathlib import Path
import re
import urllib.request

OUT=Path('/Users/chasen/.codex/worktrees/g6-p0-parser-prep-master/ontology-platform/experiments/g6-p0/supply-chain')
ROOTS={'docling':'2.145.0','docling-slim':'2.145.0','paddleocr':'3.7.0','paddlex':'3.7.0','paddlepaddle':'3.2.2'}
EXTRAS={'docling-slim':{'convert-core','format-docx','format-xlsx','format-pptx','format-markdown','format-pdf'},'paddlex':{'ocr-core'}}
LIMIT=100

def fetch(pair):
 name,version=pair
 url='https://pypi.org/pypi/'+name+('/'+version if version else '')+'/json'
 try:
  req=urllib.request.Request(url,headers={'User-Agent':'OntologyPlatform-PREP-metadata/1'})
  with urllib.request.urlopen(req,timeout=20) as f:
   raw=f.read(4*1024*1024+1)
  if len(raw)>4*1024*1024: raise ValueError('metadata_limit')
  data=json.loads(raw);i=data['info']
  return {'name':i['name'],'version':i['version'],'source':url,'retrievedAtUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'rawMetadataSha256':hashlib.sha256(raw).hexdigest(),'requiresPython':i.get('requires_python'),'licenseExpression':i.get('license_expression'),'licenseDeclared':i.get('license'),'projectUrls':i.get('project_urls'),'requiresDist':i.get('requires_dist') or [],'providesExtra':i.get('provides_extra') or [],'vulnerabilities':data.get('vulnerabilities',[]),'artifacts':[{'filename':f['filename'],'size':f['size'],'sha256':f['digests']['sha256'],'url':f['url'],'packagetype':f['packagetype'],'pythonVersion':f['python_version'],'requiresPython':f.get('requires_python'),'yanked':f['yanked']} for f in data['urls']],'status':'OBSERVED_METADATA_ONLY'}
 except Exception as exc:
  return {'name':name,'requestedVersion':version,'source':url,'status':'NOT_VERIFIED','errorClass':type(exc).__name__}

def main():
 nodes={};pending=dict(ROOTS);edges=[];excluded=[]
 while pending and len(nodes)<LIMIT:
  batch=list(pending.items())[:LIMIT-len(nodes)];pending={}
  with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
   results=list(pool.map(fetch,batch))
  for (name,_),node in zip(batch,results):nodes[name]=node
  for (name,_),node in zip(batch,results):
   for req in node.get('requiresDist',[]):
    extra_conditions=re.findall(r'extra\s*==\s*[\"\x27]([^\"\x27]+)',req)
    if extra_conditions and not set(extra_conditions)&EXTRAS.get(name,set()):
     excluded.append({'from':name,'requirement':req,'reason':'UNSELECTED_EXTRA'});continue
    m=re.match(r'([A-Za-z0-9_.-]+)(?:\[([^]]+)\])?',req)
    if not m:
     edges.append({'from':name,'requirement':req,'status':'UNPARSED_BLOCKER'});continue
    dep=re.sub(r'[-_.]+','-',m[1]).lower()
    edges.append({'from':name,'to':dep,'requirement':req,'status':'CONSTRAINT_AND_PLATFORM_NOT_RESOLVED'})
    if dep not in nodes:pending[dep]=ROOTS.get(dep)
  print(json.dumps({'observed':len(nodes),'pending':len(pending)}),flush=True)
 unresolved=sorted({e['to'] for e in edges if 'to'in e}-nodes.keys())
 report={'schemaVersion':1,'taskId':'G6-P0-PARSER-PREP-001','kind':'DECLARED_METADATA_GRAPH_NOT_INSTALL_LOCK','roots':ROOTS,'selectedExtras':{k:sorted(v) for k,v in EXTRAS.items()},'scope':'Selected root extras plus unqualified transitive declarations; markers retained, not a resolver; transitive extras not evaluated. Current transitive registry versions are observations, NOT approved candidates.','closureStatus':'BLOCKED_PENDING_PLATFORM_RESOLUTION_LICENSE_WEIGHT_REVIEW','nodes':nodes,'edges':edges,'excludedExtras':excluded,'unfetched':unresolved,'downloadedPackages':0,'downloadedWeights':0}
 OUT.mkdir(parents=True,exist_ok=True)
 (OUT/'pypi-metadata.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 print(json.dumps({'nodes':len(nodes),'edges':len(edges),'unfetched':len(unresolved),'artifactDownloads':0}))
if __name__=='__main__':main()
